import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    strs = data[1:1 + n]
    L = len(strs[0])
    res = list(strs[0])
    conflict = [False] * L
    for s in strs:
        for k in range(L):
            ch = s[k]
            if ch == '?' or conflict[k]:
                continue
            if res[k] == '?':
                res[k] = ch
            elif res[k] != ch:
                res[k] = '?'
                conflict[k] = True
    print(''.join(res))

main()

