def gen(rng):
    def fmt(ss):
        return str(len(ss)) + '\n' + '\n'.join(ss)
    tests = [fmt(['a?c', '??c', 'abc']), fmt(['adc', '??c', 'abc']), fmt(['??', '??']), fmt(['a']), fmt(['?']),
             fmt(['a', 'b']), fmt(['a', '?', 'a']), fmt(['abc']), fmt(['a?', '?b']), fmt(['ab', 'ac', 'a?'])]
    def rs(L, alpha, pq):
        return ''.join('?' if rng.random() < pq else rng.choice(alpha) for _ in range(L))
    for n, L in ((2, 3), (3, 5), (4, 6), (5, 8), (6, 10), (8, 12), (10, 15), (3, 20)):
        for alpha, pq in (('ab', 0.5), ('abc', 0.7), ('a', 0.4)):
            tests.append(fmt([rs(L, alpha, pq) for _ in range(n)]))
    # large
    tests.append(fmt([rs(10, 'a', 0.5) for _ in range(10**5)]))
    tests.append(fmt([rs(10**5, 'abcdefghijklmnopqrstuvwxyz', 0.95) for _ in range(10)]))
    base = rs(10**5, 'abcdefghijklmnopqrstuvwxyz', 0.0)
    ss = []
    for _ in range(10):
        ss.append(''.join('?' if rng.random() < 0.6 else c for c in base))
    tests.append(fmt(ss))
    tests.append(fmt([rs(1000, 'ab', 0.9) for _ in range(1000)]))
    tests.append(fmt(['?' * 10**5] * 10))
    return tests

